import { useState } from 'react';
import { Button, Group, Stack, Textarea, TextInput } from '@mantine/core';
import { useForm } from '@mantine/form';
import { useDebouncedCallback } from '@mantine/hooks';
import { SaveStatus } from './SaveStatus';

interface NoteValues {
  title: string;
  content: string;
}

function saveNote(values: NoteValues) {
  return new Promise<NoteValues>((resolve) => {
    setTimeout(() => resolve(values), 600);
  });
}

export function AutosaveServer() {
  const [status, setStatus] = useState<'idle' | 'saving' | 'saved'>('idle');
  const [savedAt, setSavedAt] = useState<string | null>(null);

  const form = useForm<NoteValues>({
    initialValues: {
      title: 'Meeting notes',
      content: '',
    },
    onValuesChange: (values) => save(values),
  });

  const dirty = form.useDirty();

  const save = useDebouncedCallback(
    async (values: NoteValues) => {
      setStatus('saving');
      await saveNote(values);
      // Saved values become the new baseline, the form is no longer dirty
      form.setInitialValues(values);
      form.resetDirty(values);
      setStatus('saved');
      setSavedAt(new Date().toLocaleTimeString());
    },
    { delay: 800, flushOnUnmount: true }
  );

  const saveNow = () => {
    save(form.getValues());
    save.flush();
  };

  return (
    <Stack>
      <Group justify="space-between">
        <SaveStatus status={status} savedAt={savedAt} dirty={dirty} />

        <Button variant="default" onClick={saveNow} disabled={!dirty || status === 'saving'}>
          Save now
        </Button>
      </Group>

      <TextInput
        size="md"
        label="Title"
        placeholder="Note title"
        {...form.getInputProps('title')}
      />

      <Textarea
        size="md"
        label="Content"
        placeholder="Start typing, the note is saved automatically"
        autosize
        minRows={5}
        maxRows={10}
        {...form.getInputProps('content')}
      />
    </Stack>
  );
}

import { Badge, Group, Loader, Text } from '@mantine/core';

interface SaveStatusProps {
  status: 'idle' | 'saving' | 'saved';
  savedAt: string | null;
  dirty: boolean;
}

export function SaveStatus({ status, savedAt, dirty }: SaveStatusProps) {
  if (status === 'saving') {
    return (
      <Group gap="xs">
        <Loader size="xs" />

        <Text size="sm">Saving…</Text>
      </Group>
    );
  }

  if (dirty) {
    return <Badge color="orange">Unsaved changes</Badge>;
  }

  return (
    <Text size="sm">
      {status === 'saved' && savedAt ? `Saved at ${savedAt}` : 'All changes saved'}
    </Text>
  );
}
